package com.spaceagent.platform.runtime.application;
import com.spaceagent.platform.runtime.api.*;import com.spaceagent.platform.runtime.domain.GraphV2OrchestrationPort;import com.spaceagent.platform.runtime.domain.multiagent.GraphV2Contract;import org.springframework.stereotype.Service;
@Service public class GraphV2OrchestrationApplicationService implements GraphV2OrchestrationApplicationApi {private final GraphV2RuntimeApplicationApi runtime;private final GraphV2OrchestrationPort graph;public GraphV2OrchestrationApplicationService(GraphV2RuntimeApplicationApi runtime,GraphV2OrchestrationPort graph){this.runtime=runtime;this.graph=graph;}public TransitionView transition(TransitionCommand c){var session=runtime.start(new GraphV2RuntimeApplicationApi.StartCommand(c.tenantId(),c.ownerUserId(),c.agentRunId(),c.bundleHash()));var request=new GraphV2Contract.Request(GraphV2Contract.VERSION,c.agentRunId()+":"+(session.cursorSequence()+1),session.graphSessionId(),c.agentRunId(),c.tenantId(),c.ownerUserId(),c.bundleHash(),new GraphV2Contract.Cursor((int)session.cursorSequence(),session.completedCommandIds(),session.pendingCommandId()),new GraphV2Contract.Limits(c.maxDepth(),c.maxAgents(),c.remainingTokenBudget()));var proposal=graph.transition(request);if(!request.requestId().equals(proposal.requestId()))throw new IllegalStateException("graph/v2 response correlation mismatch");var accepted=runtime.accept(new GraphV2RuntimeApplicationApi.AcceptCommand(c.tenantId(),c.ownerUserId(),session.graphSessionId(),proposal,c.maxDepth(),c.maxAgents(),c.remainingTokenBudget()));return new TransitionView(session,proposal,accepted);}}
